#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int arr[100005];

int main() {
    int k;
    if (scanf("%d", &k) != 1) return 0;
    int count = 0;
    for (int i = 0; i < k; i++) {
        int len;
        scanf("%d", &len);
        for (int j = 0; j < len; j++) {
            scanf("%d", &arr[count++]);
        }
    }
    qsort(arr, count, sizeof(int), cmp);
    for (int i = 0; i < count; i++) {
        printf("%d%s", arr[i], i < count - 1 ? " " : "");
    }
    printf("\n");
    return 0;
}
